function minMeetingRooms(intervals) {
  const events = [];
  for (const [s, e] of intervals) events.push([s, 1], [e, -1]);   // a start needs a room, an end frees one
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);              // at the same time, ends come first
  let rooms = 0, best = 0;
  for (const [, change] of events) {
    rooms += change;
    best = Math.max(best, rooms);
  }
  return best;
}

int minMeetingRooms(int[][] intervals) {
    int[][] events = new int[intervals.length * 2][];
    int k = 0;
    for (int[] m : intervals) {
        events[k++] = new int[]{m[0], 1};            // a start needs a room
        events[k++] = new int[]{m[1], -1};           // an end frees one
    }
    Arrays.sort(events, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));   // ends first at a tie
    int rooms = 0, best = 0;
    for (int[] ev : events) {
        rooms += ev[1];
        best = Math.max(best, rooms);
    }
    return best;
}

int minMeetingRooms(vector<vector<int>>& intervals) {
    vector<pair<int, int>> events;
    for (auto& m : intervals) {
        events.push_back({m[0], 1});                 // a start needs a room
        events.push_back({m[1], -1});                // an end frees one
    }
    sort(events.begin(), events.end());              // pairs sort by time, then -1 before +1
    int rooms = 0, best = 0;
    for (auto& [time, change] : events) {
        rooms += change;
        best = max(best, rooms);
    }
    return best;
}

function minMeetingRooms(intervals) {
  const starts = intervals.map((m) => m[0]).sort((a, b) => a - b);
  const ends = intervals.map((m) => m[1]).sort((a, b) => a - b);
  let rooms = 0, best = 0, j = 0;
  for (let i = 0; i < starts.length; i++) {
    while (ends[j] <= starts[i]) {   // a meeting ended before this one starts: its room is free
      rooms--;
      j++;
    }
    rooms++;                         // this meeting takes a room
    best = Math.max(best, rooms);
  }
  return best;
}

int minMeetingRooms(int[][] intervals) {
    int n = intervals.length;
    int[] starts = new int[n], ends = new int[n];
    for (int i = 0; i < n; i++) {
        starts[i] = intervals[i][0];
        ends[i] = intervals[i][1];
    }
    Arrays.sort(starts);
    Arrays.sort(ends);
    int rooms = 0, best = 0, j = 0;
    for (int i = 0; i < n; i++) {
        while (ends[j] <= starts[i]) {   // a meeting ended before this one starts: its room is free
            rooms--;
            j++;
        }
        rooms++;                         // this meeting takes a room
        best = Math.max(best, rooms);
    }
    return best;
}

int minMeetingRooms(vector<vector<int>>& intervals) {
    vector<int> starts, ends;
    for (auto& m : intervals) {
        starts.push_back(m[0]);
        ends.push_back(m[1]);
    }
    sort(starts.begin(), starts.end());
    sort(ends.begin(), ends.end());
    int rooms = 0, best = 0;
    size_t j = 0;
    for (int start : starts) {
        while (ends[j] <= start) {       // a meeting ended before this one starts: its room is free
            rooms--;
            j++;
        }
        rooms++;                         // this meeting takes a room
        best = max(best, rooms);
    }
    return best;
}
